const body = $json.body ?? $json;
const mode = body.mode || 'demo';
const kind = body.kind || 'nan_loss';
const bridge = body.bridge_base_url || 'https://REPLACE_WITH_NGROK.ngrok-free.app';

return [{
  json: {
    mode,
    kind,
    dataset: String(body.dataset || 'auto').toLowerCase(),
    dataset_path: String(body.dataset_path || ''),
    dataset_url: String(body.dataset_url || ''),
    image_size: Number(body.image_size || 0),
    healthy_epochs: Number(body.healthy_epochs || 2),
    broken_epochs: Number(body.broken_epochs || 1),
    resume_epochs: Number(body.resume_epochs || 2),
    train_size: Number(body.train_size || 2000),
    val_size: Number(body.val_size || 1000),
    batch_size: Number(body.batch_size || 64),
    max_epochs: Number(body.max_epochs || 6),
    lr: Number(body.lr || 0.01),
    seed: Number(body.seed || 42),
    bridge_base_url: String(bridge).replace(/\/$/, ''),
    requested_at: new Date().toISOString()
  }
}];

const input = $('Normalize Input').item.json;
const catalog = $json || {};
const custom = catalog.custom || [];
let dataset = String(input.dataset || 'auto').toLowerCase().trim();
let dataset_path = input.dataset_path || '';
let dataset_url = input.dataset_url || '';
let resolved_how = 'explicit';

if (dataset === 'auto') {
  if (dataset_url) {
    dataset = 'custom';
    resolved_how = 'url';
  } else if (dataset_path) {
    dataset = 'custom';
    resolved_how = 'path';
  } else if (custom.length) {
    dataset = 'custom';
    dataset_path = custom[0].path;
    resolved_how = 'first_custom_folder';
  } else {
    dataset = 'mnist';
    resolved_how = 'default_mnist';
  }
}

return [{
  json: {
    ...input,
    dataset,
    dataset_path,
    dataset_url,
    resolved_how,
    catalog_ids: (catalog.datasets || []).map(d => d.id)
  }
}];

function safe(name) {
  try {
    const node = $(name);
    if (node.first) {
      const item = node.first();
      if (item && item.json && Object.keys(item.json).length) return item.json;
    }
  } catch (e) {}
  try {
    const all = $(name).all();
    if (all && all.length && all[all.length - 1].json) return all[all.length - 1].json;
  } catch (e) {}
  try {
    return $(name).item.json;
  } catch (e) {}
  return {};
}

const incoming = ($input.first && $input.first().json) || $json || {};
const analyzed = safe('Analyze and Apply');
const status = Object.keys(safe('Final Status')).length ? safe('Final Status') : incoming;
const compare = Object.keys(safe('Compare Recovery')).length ? safe('Compare Recovery') : (status.recovery_report || {});
const snapshot = safe('Snapshot Before');
const metrics = safe('Get Metrics');
const checkpoints = safe('List Checkpoints');
const resolved = safe('Resolve Dataset');
const started = safe('Start Training');
const normalized = safe('Normalize Input');
const decision = analyzed.decision || {};
const mcpFromAnalyze = analyzed.mcp_tools_called || analyzed._meta?.mcp_tools_called || [];
const mcpFromStatus = status.mcp_tools_called || status._meta?.mcp_tools_called || [];
const mcpFromCompare = compare.mcp_tools_called || compare._meta?.mcp_tools_called || [];
const tools = [...mcpFromAnalyze, ...mcpFromStatus, ...mcpFromCompare].map(t => t.tool);
const uniqueTools = [...new Set(tools)];
const story = analyzed.mcp_story || status.mcp_story || `n8n → bridge → ${uniqueTools.map(t => 'MCP:' + t).join(' → ')}`;
const recoverySuccess = compare.recovery_success === true;
const datasetInfo = started.dataset || status.dataset || {
  requested: resolved.dataset,
  resolved_how: resolved.resolved_how,
  path: resolved.dataset_path
};
const datasetName = datasetInfo.name || datasetInfo.id || resolved.dataset || 'auto';
const banner = [
  '╔══════════════════════════════════════════╗',
  '║   TRAINGUARD · DATASET + MCP             ║',
  '╠══════════════════════════════════════════╣',
  `║ dataset: ${datasetName}`.padEnd(43, ' ') + '║',
  `║ action: ${decision.action || status.last_action?.action}`.padEnd(43, ' ') + '║',
  `║ recovery_success: ${recoverySuccess}`.padEnd(43, ' ') + '║',
  '║ dashboard: http://127.0.0.1:8787/dashboard ║',
  '╚══════════════════════════════════════════╝'
].join('\n');

const summary = {
  project: 'TrainGuard',
  dataset: datasetInfo,
  trainer: 'pytorch_tiny_cnn',
  mode: resolved.mode || normalized.mode,
  kind: resolved.kind || normalized.kind,
  called_via_mcp: true,
  decided_by: decision.decided_by || 'unknown',
  model: decision.model || null,
  mcp_banner: banner,
  mcp_story: story,
  mcp_dashboard: 'http://127.0.0.1:8787/dashboard',
  mcp_integration: 'n8n -> bridge -> MCP Client -> TrainGuard tools (+ Gemini si USE_GEMINI)',
  mcp_tools_from_analyze: mcpFromAnalyze,
  action: decision.action || (status.last_action && status.last_action.action),
  confidence: decision.confidence,
  reason: decision.reason || (status.last_action && status.last_action.reason),
  evidence: decision.evidence,
  applied: analyzed.applied,
  snapshot_before_fault: snapshot.best_checkpoint || snapshot.snapshot_before_fault || compare.before || status.snapshot_before_fault,
  recovery: {
    best_acc_before: compare.best_acc_before,
    best_acc_after: compare.best_acc_after,
    best_acc_delta: compare.best_acc_delta,
    preserved_best: compare.preserved_best,
    resumed: compare.resumed,
    latest_healthy: compare.latest_healthy,
    recovery_success: compare.recovery_success,
    best_sha256_at_fault: compare.best_sha256_at_fault,
    best_sha256_now: compare.best_sha256_now
  },
  run_id: status.run_id || decision.run_id,
  status: status.status,
  epoch: status.epoch,
  lr: status.lr,
  fault: status.fault,
  best_acc: status.best_acc,
  best_loss: status.best_loss,
  last_action: status.last_action,
  latest_metrics: metrics.metrics || status.metrics,
  checkpoints: checkpoints.checkpoints || status.checkpoints,
  message: `TrainGuard ${datasetName} via ${decision.decided_by || 'MCP'}: ${decision.action || (status.last_action && status.last_action.action)} recovery_success=${compare.recovery_success} (best ${compare.best_acc_before} → ${compare.best_acc_after})`
};

return [{ json: summary }];
